/* 課程網站入口（2026-10-16 三級密碼）
   - 網站不放明碼：每組密碼只有 SHA-256 雜湊（比對用）＋「被這組密碼鎖住的內容金鑰」。
   - 內容用兩把內容金鑰 AES-GCM 加密：學員金鑰（U00～U06）、全部金鑰（U00～U12）。
   - 等級：student 前兩篇／all 全部／admin 全部＋線上新增、停用密碼（存在 Netlify 的 keyring 函式，也只存雜湊）。
   - 本機開發時 GATE = null，不設門；scripts/deploy_site.py 部署時才把雜湊與加密內容填進來。 */
const GATE = {"ring": [{"h": "aa6559d994875bd92f9e9278788469288878c52a2b05ef80dea5623a4edc2949", "lvl": "student", "label": "\u5b78\u54e1\uff08\u4eca\u5929\u7684\u5925\u4f34\uff09", "w": {"s": {"iv": "enbZXR+kwui+Hd7A", "ct": "9LLV07tAap2c223cYpNb9dHGbBIONpwr2hvAUmnEJmuNupy7nUbSGZbdeY3mFuNKkNXcO51rgpJKc39UwWSJsJL+6ky+Kl1hQTdtpXRf40k="}}}, {"h": "61626199cb563f36a4d3785cd08196021acd3da85d97c243ad5700506b710a6e", "lvl": "all", "label": "\u5168\u90e8\u55ae\u5143", "w": {"s": {"iv": "5PLoe1FPMZRX8YVP", "ct": "jljhNCX5vYbaxXUnEK6+7YmsTiPDr8vKeHIcZVAvNczqhGAFyAYD+Uq9GSkklz9HTrvOnKD9QaTv0rQPGXyrEbcjEWmkNyZfC5KXtid1yt8="}, "a": {"iv": "g6mBGguvyaAb9sQh", "ct": "yedR8YquWWWUZ49cf9+hSYYS3jpG91U1m5ZN/amg8Djl5OoCAi0QUGaXh6OIaSUYmLfzs0CViEIID+72y7Q7S7LwVb4XMTLFaoi7H5B1QlQ="}}}, {"h": "a62403edaf813daa73e28d16d0f5244e13720130d85fdae6ab7508708d1bc04d", "lvl": "admin", "label": "\u7d42\u6975\uff08\u7ba1\u7406\u5bc6\u78bc\uff09", "w": {"s": {"iv": "dw35zQGxN3RUXKkI", "ct": "brZUFkfn5oEXdACckwqbe1nJXyNSIN6uB7xpUT7NPHwJADoARBps+0GQ7+8b3/5MRlHJ11x/wV3aIOBvyNTosxH88yQISURP8ZfbryDXpSw="}, "a": {"iv": "tKzPnuE0KOcOVQsK", "ct": "Owe1bMboVHR9pSvTViF73rOoAgarqtqwwHxYXvAqKSJntOWPPRiN8cOPOz/7VHCUJsK+wd4nVuiqAOiaGupM/5X4ApYcZrnSSelTJ6uNbY0="}}}], "home": {"student": {"iv": "uMBSl2OKUzTD5rSs", "ct": ""}, "all": {"iv": "/2xVev5/nJygdVLb", "ct": ""}}, "extra": {"all": {"iv": "srIdela4upbvMBBj", "ct": ""}}};

const SK = 'cobotgate2';
const API = '/.netlify/functions/keyring';
const te = new TextEncoder(), td = new TextDecoder();
const hex = b => [...new Uint8Array(b)].map(x => x.toString(16).padStart(2, '0')).join('');
const unhex = h => new Uint8Array(h.match(/../g).map(x => parseInt(x, 16)));
const b64d = s => Uint8Array.from(atob(s), c => c.charCodeAt(0));
const b64e = u => { let s = ''; new Uint8Array(u).forEach(c => s += String.fromCharCode(c)); return btoa(s); };
const sha = s => crypto.subtle.digest('SHA-256', te.encode(s));
const pwKey = async pw => new Uint8Array(await sha('cobot|' + pw));
const key = (raw, use) => crypto.subtle.importKey('raw', raw, 'AES-GCM', false, [use]);

async function unlock(blob, raw){
  return td.decode(await crypto.subtle.decrypt({ name: 'AES-GCM', iv: b64d(blob.iv) }, await key(raw, 'decrypt'), b64d(blob.ct)));
}
async function lock(text, raw){
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const ct = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, await key(raw, 'encrypt'), te.encode(text));
  return { iv: b64e(iv), ct: b64e(ct) };
}

export const enabled = () => !!GATE;
const lvlName = { student: '學員（前兩篇）', all: '全部單元', admin: '終極（可管理密碼）' };
export const levelName = l => lvlName[l] || l;

/* 鑰匙圈＝部署時內建的密碼＋線上新增的密碼；被停用的內建密碼（終極除外）不算 */
async function remoteRing(){
  try{ const r = await fetch(API, { cache: 'no-store' }); if (r.ok) return await r.json(); }catch(_){}
  return { entries: [], disabled: [] };
}
async function ring(){
  const d = await remoteRing(), off = new Set(d.disabled || []);
  return GATE.ring.filter(e => e.lvl === 'admin' || !off.has(e.h)).concat((d.entries || []).filter(e => !off.has(e.h)));
}

/* 輸入密碼：SHA-256 比對 → 用密碼解開內容金鑰 → 存在這個分頁（關掉分頁就要重新輸入） */
export async function login(pw){
  const h = hex(await sha(pw));
  const e = (await ring()).find(x => x.h === h);
  if (!e) return null;
  const raw = await pwKey(pw), keys = {};
  for (const k of ['s', 'a']) if (e.w[k]) keys[k] = await unlock(e.w[k], raw);
  try{ sessionStorage.setItem(SK, JSON.stringify({ lvl: e.lvl, keys, label: e.label || '' })); }catch(_){}
  return e.lvl;
}

export function logout(){ try{ sessionStorage.removeItem(SK); }catch(_){} }

const homeKey = s => s.lvl === 'student' ? ['student', s.keys.s] : ['all', s.keys.a];

/* 目前登入狀態：金鑰要真的解得開首頁才算（改 sessionStorage 冒充沒用） */
export async function session(){
  if (!GATE) return { lvl: 'open' };
  try{
    const s = JSON.parse(sessionStorage.getItem(SK));
    const [k, raw] = homeKey(s);
    s.home = await unlock(GATE.home[k], unhex(raw));
    return s;
  }catch(_){ return null; }
}

export async function homeHtml(s){ return s.home || unlock(GATE.home[homeKey(s)[0]], unhex(homeKey(s)[1])); }

/* 閱讀器用：沒登入 → 回首頁登入；可看全部 → 解開隱藏單元的書目、目錄、提示詞位置、程式碼清單 */
export async function gateReader(){
  if (!GATE) return {};
  const s = await session();
  if (!s){
    location.replace('index.html?next=' + encodeURIComponent('reader.html' + location.search));
    await new Promise(() => {});
  }
  if (s.lvl === 'student' || !GATE.extra) return {};
  const ex = JSON.parse(await unlock(GATE.extra.all, unhex(s.keys.a)));
  const _fetch = window.fetch.bind(window);
  window.fetch = async (u, o) => {
    const r = await _fetch(u, o);
    const add = ex.json[String(u).split('?')[0]];
    if (!add || !r.ok) return r;
    const j = await r.json();
    return new Response(JSON.stringify(Object.assign(j, add)), { status: 200, headers: { 'Content-Type': 'application/json' } });
  };
  return ex.books || {};
}

/* ---------- 密碼管理（只有終極密碼登入才看得到；伺服器端再用終極密碼的雜湊把關） ---------- */
export async function adminList(){
  const d = await remoteRing(), off = new Set(d.disabled || []);
  const rows = GATE.ring.map(e => ({ h: e.h, lvl: e.lvl, label: e.label, builtin: true, off: e.lvl !== 'admin' && off.has(e.h) }))
    .concat((d.entries || []).map(e => ({ h: e.h, lvl: e.lvl, label: e.label, t: e.t, builtin: false, off: off.has(e.h) })));
  return rows;
}
async function post(adminPw, body){
  const r = await fetch(API, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(Object.assign({ admin: adminPw }, body)) });
  const j = await r.json().catch(() => ({}));
  if (!r.ok) throw new Error(j.error || ('伺服器回應 ' + r.status));
  return j;
}
/* 新增或改密碼：在瀏覽器裡用新密碼把內容金鑰鎖起來，只把「雜湊＋鎖好的金鑰」送上去 */
export async function adminAdd(adminPw, label, lvl, newPw){
  const s = await session();
  if (!s || s.lvl !== 'admin') throw new Error('請先用終極密碼登入');
  if (!newPw || newPw.length < 6) throw new Error('新密碼至少 6 個字');
  const h = hex(await sha(newPw));
  if (GATE.ring.some(e => e.h === h && e.lvl === 'admin')) throw new Error('不能和終極密碼一樣');
  const raw = await pwKey(newPw);
  const w = { s: await lock(s.keys.s, raw) };
  if (lvl === 'all') w.a = await lock(s.keys.a, raw);
  return post(adminPw, { op: 'add', entry: { h, lvl, label, w } });
}
export const adminRemove = (adminPw, h) => post(adminPw, { op: 'remove', h });
export const adminDisable = (adminPw, h) => post(adminPw, { op: 'disable', h });
export const adminEnable = (adminPw, h) => post(adminPw, { op: 'enable', h });
